    "\nfrom sklearn.cluster import KMeans\nfrom scipy.optimize import curve_fit\nfrom scipy.spatial.distance import pdist, squareform\nimport time\n\ndef expv(h,c0,c1,a): return c0+c1*(1-np.exp(-3*h/a))\n\ndef emp_vario(P,z,nb=12):\n    D=pdist(P); G=0.5*pdist(z[:,None],'sqeuclidean')\n    maxd=D.max()*0.5; bins=np.linspace(0,maxd,nb+1)\n    idx=np.digitize(D,bins)-1; ok=(idx>=0)&(idx<nb)\n    cnt=np.bincount(idx[ok],minlength=nb); s=np.bincount(idx[ok],G[ok],minlength=nb)\n    m=cnt>0; hc=(0.5*(bins[1:]+bins[:-1]))[m]\n    return hc, s[m]/cnt[m], cnt[m], maxd\n\ndef fit_vario(P,z):\n    hc,g,n,maxd=emp_vario(P,z); v=max(np.var(z),1e-9)\n    try:\n        p,_=curve_fit(expv,hc,g,p0=[0.1*v,0.9*v,maxd/2],sigma=1/np.sqrt(n),\n                      bounds=([0,1e-9,maxd/50],[2*v,3*v,maxd*4]),maxfev=4000)\n    except Exception:\n        p=np.array([0.1*v,0.9*v,maxd/2])\n    return p\n\ndef ebk(P,z,gxy,subset_size=100,n_sim=30,k=15,seed=0):\n    rng=np.random.default_rng(seed)\n    nsub=max(1,len(z)//subset_size)\n    km=KMeans(nsub,n_init=1,random_state=seed).fit(P)\n    lab=km.labels_\n    tree=cKDTree(P); _,nn=tree.query(gxy,k=k)\n    gsub=cKDTree(km.cluster_centers_).query(gxy)[1]\n    pred=np.zeros(len(gxy)); se=np.zeros(len(gxy))\n    for s in range(nsub):\n        Ps=P[lab==s]; zs=z[lab==s]\n        cells=np.nonzero(gsub==s)[0]\n        if len(cells)==0: continue\n        p0=fit_vario(Ps,zs)\n        # simulation spectrum: simulate from fitted model, re-estimate\n        Ds=squareform(pdist(Ps)); C=p0[1]*np.exp(-3*Ds/p0[2])+np.eye(len(zs))*(p0[0]+1e-9*(p0[0]+p0[1]))\n        L=np.linalg.cholesky(C)\n        params=[p0]\n        for _ in range(n_sim-1):\n            params.append(fit_vario(Ps, L@rng.standard_normal(len(zs))))\n        # rescale simulated variograms to keep sill consistent w/ data (EBK uses scaled spectra)\n        Xn=P[nn[cells]]; zn=z[nn[cells]]                 # (m,k,2),(m,k)\n        Dn=np.linalg.norm(Xn[:,:,None,:]-Xn[:,None,:,:],axis=-1)\n        D0=np.linalg.norm(Xn-gxy[cells][:,None,:],axis=-1)\n        m=len(cells); mu_all=[]; var_all=[]\n        for (c0,c1,a) in params:\n            sill=c0+c1\n            Cm=sill-expv(Dn,c0,c1,a); Cm[:,np.arange(k),np.arange(k)]=sill\n            c0v=sill-expv(D0,c0,c1,a); c0v[D0==0]=sill\n            A=np.ones((m,k+1,k+1)); A[:,:k,:k]=Cm; A[:,k,k]=0\n            b=np.ones((m,k+1)); b[:,:k]=c0v\n            w=np.linalg.solve(A,b[...,None])[...,0]\n            mu_all.append((w[:,:k]*zn).sum(1))\n            var_all.append(sill-(w*b).sum(1))\n        mu_all=np.array(mu_all); var_all=np.maximum(np.array(var_all),0)\n        pred[cells]=mu_all.mean(0)\n        se[cells]=np.sqrt(var_all.mean(0)+mu_all.var(0))   # mixture variance\n    return pred,se\n\nP=xy.copy(); gxy=np.c_[gx,gy]\nres={}\nfor var in ['temp','salinity']:\n    t0=time.time()\n    res[var]=ebk(P,om[var].values.astype(float),gxy)\n    print(var,time.time()-t0, np.percentile(res[var][0],[0,1,50,99,100]))\n",
    "\nimport warnings; warnings.filterwarnings('ignore')\ndef ebk(P,z,gxy,subset_size=100,n_sim=30,k=15,seed=0):\n    rng=np.random.default_rng(seed)\n    nsub=max(1,len(z)//subset_size)\n    km=KMeans(nsub,n_init=1,random_state=seed).fit(P)\n    tree=cKDTree(P); _,nn=tree.query(gxy,k=k)\n    _,subidx=tree.query(km.cluster_centers_,k=subset_size)\n    gsub=cKDTree(km.cluster_centers_).query(gxy)[1]\n    pred=np.full(len(gxy),np.nan); se=np.full(len(gxy),np.nan)\n    for s in range(nsub):\n        cells=np.nonzero(gsub==s)[0]\n        if len(cells)==0: continue\n        Ps=P[subidx[s]]; zs=z[subidx[s]]\n        p0=fit_vario(Ps,zs)\n        Ds=squareform(pdist(Ps)); C=p0[1]*np.exp(-3*Ds/p0[2])+np.eye(len(zs))*(p0[0]+1e-6*(p0[0]+p0[1]))\n        L=np.linalg.cholesky(C)\n        params=[p0]+[fit_vario(Ps, L@rng.standard_normal(len(zs))) for _ in range(n_sim-1)]\n        Xn=P[nn[cells]]; zn=z[nn[cells]]\n        Dn=np.linalg.norm(Xn[:,:,None,:]-Xn[:,None,:,:],axis=-1)\n        D0=np.linalg.norm(Xn-gxy[cells][:,None,:],axis=-1)\n        m=len(cells); mu_all=[]; var_all=[]\n        for (c0,c1,a) in params:\n            sill=c0+c1\n            Cm=sill-expv(Dn,c0,c1,a); Cm[:,np.arange(k),np.arange(k)]=sill+1e-9*sill\n            c0v=sill-expv(D0,c0,c1,a); c0v[D0==0]=sill\n            A=np.ones((m,k+1,k+1)); A[:,:k,:k]=Cm; A[:,k,k]=0\n            b=np.ones((m,k+1)); b[:,:k]=c0v\n            w=np.linalg.solve(A,b[...,None])[...,0]\n            mu_all.append((w[:,:k]*zn).sum(1)); var_all.append(sill-(w*b).sum(1))\n        mu_all=np.array(mu_all); var_all=np.maximum(np.array(var_all),0)\n        pred[cells]=mu_all.mean(0); se[cells]=np.sqrt(var_all.mean(0)+mu_all.var(0))\n    return pred,se\n\nres={}\nfor var in ['temp','salinity']:\n    t0=time.time()\n    res[var]=ebk(P,om[var].values.astype(float),gxy)\n    print(var,time.time()-t0, np.nanpercentile(res[var][0],[0,1,50,99,100]), np.isnan(res[var][0]).sum())\n",
